import hashlib
import json
import sqlite3
from pathlib import Path


SUPPLIER_HASH = "bc56b6d76807f3fac822aad0205563161b9662b1c08402ba3af95a6fd548bc90"
CLAIM_HASH = "b25ca4244fbedbefa76a25b383be78bbac658e99cea56cabc2ede8f20e697c81"
EXPECTED_SOURCES = {"SUP-00018", "SUP-00019"}


def _db(ws):
    candidates = [
        Path(ws).parent / "system" / "yonyou_nc_ledger" / "state.db",
        Path(ws) / "system" / "yonyou_nc_ledger" / "state.db",
    ]
    for path in candidates:
        if path.exists():
            return path
    raise FileNotFoundError("yonyou_nc_ledger state.db not found")


def _digest(con, table):
    rows = [dict(row) for row in con.execute("SELECT * FROM " + table + " ORDER BY rowid")]
    payload = json.dumps(rows, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _reason_matches(reason):
    compact = "".join(str(reason).split())
    return ("税号" in compact and "历史" in compact and "名称" in compact
            and "归一" in compact and compact.startswith("同"))


def _check_variant(ws, source):
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        table = con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='supplier_variant_flags'"
        ).fetchone()
        if table is None:
            return {"score": 0, "detail": "supplier_variant_flags does not exist"}
        rows = [dict(row) for row in con.execute(
            "SELECT supplier_id, normalized_supplier_id, reason, operator_id, status "
            "FROM supplier_variant_flags ORDER BY supplier_id, mapping_id"
        )]
    sources = {row["supplier_id"] for row in rows}
    if sources != EXPECTED_SOURCES or len(rows) != len(EXPECTED_SOURCES):
        return {"score": 0, "detail": f"unexpected mapping rows: {rows!r}"}
    row = next((row for row in rows if row["supplier_id"] == source), None)
    if row is None:
        return {"score": 0, "detail": f"mapping missing for {source}"}
    if (row["normalized_supplier_id"] != "SUP-00017" or row["operator_id"] != "周启衡"
            or row["status"] != "ACTIVE" or not _reason_matches(row["reason"])):
        return {"score": 0, "detail": f"unexpected mapping for {source}: {row!r}"}
    return {"score": 1, "detail": f"mapping matches target for {source}"}


def check_variant_00018(ws):
    return _check_variant(ws, "SUP-00018")


def check_variant_00019(ws):
    return _check_variant(ws, "SUP-00019")


def _unchanged(ws, table, expected):
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        actual = _digest(con, table)
    if actual != expected:
        return {"score": 0, "detail": f"{table} changed"}
    return {"score": 1, "detail": f"{table} unchanged"}


def check_supplier_master_unchanged(ws):
    return _unchanged(ws, "supplier_master", SUPPLIER_HASH)


def check_expense_claims_unchanged(ws):
    return _unchanged(ws, "expense_claims", CLAIM_HASH)
